head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.pageId = "ULDTMS03170";
scwin.scrollTop = "";

///////// 2. 초기화 영역 /////////
scwin.onpageload = function() {
	try {

					// 조회
					scwin.fnSearch("Y", 1);
	                // 초기화
	                pgl_list.hide();

	} catch (ex) {
		$c.exception.handleError(ex, { context : "ULDTMS03170.onpageload" });
	}
};

///////// 3. 컴포넌트 이벤트 영역 /////////
            scwin.btn_search_onclick = function (e) {

                scwin.fnSearch("Y", 1);
            };

            scwin.sbx_page_onchange = function (info) {

                scwin.fnSearch("Y", 1);
            };

            scwin.pgl_list_onclick = function (index) {

                scwin.fnSearch("N", index);
            };

            scwin.ibx_formCd_onkeyup = function (e) {

                if (e.key === "Enter") {                    
                    scwin.fnSearch("Y", 1);
                }
            };

            scwin.ibx_formKorNm_onkeyup = function (e) {

                if (e.key === "Enter") {                    
                    scwin.fnSearch("Y", 1);
                }
            };

            scwin.ibx_formVer_onkeyup = function (e) {

                if (e.key === "Enter") {                    
                    scwin.fnSearch("Y", 1);
                }
            };

            scwin.grd_list_oncellclick = async function (rowIndex, columnIndex, columnId) {

                if (columnId === "formKorNm") {                    
                    const params = {};
                    params.formCd = dlt_list.getCellData(rowIndex, "formCd");
                    params.formKorNm = dlt_list.getCellData(rowIndex, "formKorNm");
                    params.formVer = dlt_list.getCellData(rowIndex, "formVer");
                    params.storageId = scwin.pageId;

                    // 위치 정보 저장
                    $c.tms.setKeywordSave(scwin.pageId, grd_list, dma_search);                                        

					const url_ = "/ui/TMS/ULDTMS03180.xml";
                	const options = {
                    	id: "ULDTMS03180_POP",
                    	popupName: "기재상의 주의 관리 상세",
                    	width: "600",
                    	height: "320",
                    	frameModal: "top"
                	};

                    const result = await $c.win.openPopup(url_, options, params);
                    if (!$c.util.isEmpty(result) && result.refreshYn === "Y") {
                        //  그리드 위치 처리
                        if (!$c.util.isEmpty(result.storageId)) {                        
                            scwin.scrollTop = $c.tms.getKeywordSave(result.storageId, dma_search); 
                        }
                        scwin.fnSearch();
                    } else {
                        $c.tms.delKeyword(scwin.pageId);
                    }
                }
            };

///////// 4. 서브미션 콜백 영역 /////////
            scwin.sbm_list_submitdone = function (e) {

                // 조회 성공인 경우
				const result = e.responseJSON;
                if (result.success) {
                    const obj = result.body;

                    // 시작 번호 계산 (페이지별 연속 번호)
                    const currentPage = parseInt(dma_search.get("page")) || 1;
                    const pageSize = parseInt(dma_search.get("size")) || 10;                                                    
                    const startIndex = (currentPage - 1) * pageSize;                   

                    // 페이지별 시작 번호 계산 및 그리드에 설정                    
                    grd_list.setStartRowNumber(startIndex);

                    const firstYn = dma_search.get("totalYn");
                    let totalCnt = 0;

                    // 최초 조회일 경우에만 전체 건수를 구하여 전역변수에 담는다.
                    if (firstYn === "Y") {
                        if (!$c.util.isEmpty(obj.totalCount)) {
                            tbx_totCnt.setValue($c.num.formatNumber(obj.totalCount));
                            totalCnt = parseInt(obj.totalCount) || 0;
                        }        

                        // 데이터가 있는 경우에만 페이지 리스트 표시
                        if (totalCnt > 0) { 
                            pgl_list.setCount(obj.totalPages);
                            pgl_list.show();
                        } else {
                            pgl_list.hide();
                        }            
                    }

                    // 재조회 여부 체크
                    if (!$c.util.isEmpty(scwin.scrollTop)) {
                        grd_list.setScrollTop(scwin.scrollTop);                        
                        scwin.scrollTop = "";
                    }                    
                } else {
					$c.win.alert(result.message);
				}
            };

///////// 5. 일반/업무 함수 영역 /////////
            scwin.fnSearch = function (totYn, index) {

                dma_search.set("totalYn", totYn);
                dma_search.set("page", index);
                dma_search.set("size", sbx_page.getValue());

                // 조회 
                $c.sbm.execute(sbm_list, dma_search.getJSON());
            };
